export class SheetError extends Error {}

const ADDR = /^([A-Za-z]{1,2})([0-9]{1,3})$/

export function colIndex(letters) {
  return letters.length === 1
    ? letters.charCodeAt(0) - 64
    : 26 + (letters.charCodeAt(0) - 65) * 26 + (letters.charCodeAt(1) - 64)
}
export function colName(i) {
  if (i <= 26) return String.fromCharCode(64 + i)
  const j = i - 27
  return String.fromCharCode(65 + Math.floor(j / 26)) + String.fromCharCode(65 + (j % 26))
}
// returns {col,row} or null
export function parseAddr(s) {
  const m = ADDR.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  return { col: colIndex(m[1].toUpperCase()), row }
}
export const addrKey = (col, row) => colName(col) + row

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(line)
    const addr = m[1]
    const a = parseAddr(addr)
    if (!a) throw new SheetError(`error: line ${i + 1}: invalid cell address ${addr}`)
    const key = addrKey(a.col, a.row)
    if (cells.has(key)) throw new SheetError(`error: line ${i + 1}: cell ${key} is declared twice`)
    cells.set(key, { col: a.col, row: a.row, key, content: m[2] })
  })
  return [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)
}
